import { createComponent as _$createComponent } from "solid-js/web";
// Keyway Dashboard — entry point (Solid.js)

import { render } from "solid-js/web";
import { createSignal, Match, Switch } from "solid-js";
import { initState, state } from "./state";
import { connectSSE, connectWS, startMetricPolling } from "./api";
import { Layout } from "./components/layout";
import { parseHash } from "./router";

// Views
import { Overview } from "./views/overview";
import { Traffic } from "./views/traffic";
import { Workers } from "./views/workers";
import { Routes } from "./views/routes";
import { Scripts } from "./views/scripts";
import { Hooks } from "./views/hooks";
const routes = [
// OBSERVE
{
  group: "observe",
  path: "/",
  label: "Overview",
  icon: "◉"
}, {
  group: "observe",
  path: "/traffic",
  label: "Traffic",
  icon: "▤"
}, {
  group: "observe",
  path: "/workers",
  label: "Workers",
  icon: "▦"
},
// MANAGE
{
  group: "manage",
  path: "/routes",
  label: "Routes",
  icon: "⇄"
}, {
  group: "manage",
  path: "/scripts",
  label: "Scripts",
  icon: "λ"
}, {
  group: "manage",
  path: "/hooks",
  label: "Hooks",
  icon: "↩"
}];
function App() {
  const s = state();
  const [currentPath, setCurrentPath] = createSignal(parseHash(location.hash).path);
  function navigate(path, ctx) {
    let hash = path;
    if (ctx) {
      const params = new URLSearchParams();
      for (const [k, v] of Object.entries(ctx)) {
        if (v != null) params.set(k, String(v));
      }
      const qs = params.toString();
      if (qs) hash = `${path}?${qs}`;
    }
    location.hash = hash;
    setCurrentPath(path);
  }
  function openConsole(cmd) {
    if (cmd) s.setPendingConsoleCmd(cmd);
    s.setDrawerOpen(true);
  }

  // Listen for hash changes (back/forward)
  window.onhashchange = () => {
    const {
      path
    } = parseHash(location.hash);
    setCurrentPath(path);
  };
  return _$createComponent(Layout, {
    routes: routes,
    currentPath: currentPath,
    onNavigate: navigate,
    get children() {
      return _$createComponent(Switch, {
        get fallback() {
          return _$createComponent(Overview, {
            onNavigate: navigate,
            onOpenConsole: openConsole
          });
        },
        get children() {
          return [_$createComponent(Match, {
            get when() {
              return currentPath() === "/";
            },
            get children() {
              return _$createComponent(Overview, {
                onNavigate: navigate,
                onOpenConsole: openConsole
              });
            }
          }), _$createComponent(Match, {
            get when() {
              return currentPath() === "/traffic";
            },
            get children() {
              return _$createComponent(Traffic, {
                onNavigate: navigate
              });
            }
          }), _$createComponent(Match, {
            get when() {
              return currentPath() === "/workers";
            },
            get children() {
              return _$createComponent(Workers, {
                onNavigate: navigate
              });
            }
          }), _$createComponent(Match, {
            get when() {
              return currentPath() === "/routes";
            },
            get children() {
              return _$createComponent(Routes, {
                onNavigate: navigate
              });
            }
          }), _$createComponent(Match, {
            get when() {
              return currentPath() === "/scripts";
            },
            get children() {
              return _$createComponent(Scripts, {});
            }
          }), _$createComponent(Match, {
            get when() {
              return currentPath() === "/hooks";
            },
            get children() {
              return _$createComponent(Hooks, {});
            }
          })];
        }
      });
    }
  });
}

// Boot
initState();
render(() => _$createComponent(App, {}), document.getElementById("app"));
connectSSE();
connectWS();
startMetricPolling();